<?php require 'includes/db.php'; require 'includes/auth.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Use a valid name, email and password of at least 8 characters.';else try{$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=(int)db()->lastInsertId();header('Location: account.php');exit;}catch(PDOException $e){$error='That email is already registered.';}} require 'includes/header.php';?><div class="form-card"><h1>Create account</h1><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="btn">Sign Up</button></form><p>Already registered? <a href="login.php">Log in</a></p></div><?php require 'includes/footer.php';?>